sketches.source:
setcpm(60/4)

// Steady rain on the new leaves
rain: s("rain").slow(4).intensity(.4).gain(.28)

// Drops falling from the branches at random points around you, some close, some far
drips: s("drip*8?0.5").azimuth(rand.range(-180, 180)).elevation(rand.range(0, 50))
  .distance(rand.range(1, 4)).seed("spring").gain(.14)

// A blackbird singing through the shower, off to the left
blackbird: s("bird").slow(3).azimuth(-50).distance(5).gain(.18)

// Thunder far away, now and then
thunder: s("<~ ~ ~ [~ lt] ~ ~ ~ ~>").speed(.4).lpf(250).distance(12).room(.8).size(.95).gain(.4)

setcpm(60/4)

// Eight bars: the storm builds, breaks overhead and moves away
rain: s("rain").intensity("<.2 .35 .55 .8 .8 .6 .4 .25>").gain(.3)

// Thunder moves bar by bar: from the left, up overhead and close, then away behind you
thunder: s("<[~ lt] ~ [lt ~ ~ lt] lt [lt lt ~ lt] lt ~ [~ lt]>").speed(.4).lpf(300)
  .azimuth("<-120 -90 -45 0 30 90 140 170>").elevation("<10 20 45 70 70 45 20 10>")
  .distance("<12 9 5 2 2 5 9 12>").room(.9).size(.95).gain(.5)

// Gusts: unrelated noise in each ear, wide and enveloping, rising and falling with the storm
gusts: s("pink").icorr(.15).hpf(200).lpf(sine.range(400, 2000).slow(8))
  .gain("<.03 .05 .08 .12 .12 .08 .05 .03>")

// The gutter overflows on your right while the rain is heavy
gutter: s("drip*16?0.4").azimuth(70).distance(2).mask("<0 0 1 1 1 1 1 0>").seed("gutter").gain(.12)

setcpm(60/4)

// The stream runs slowly past you, from left to right, over sixteen bars
stream: s("stream").slow(4).intensity(.6).azimuth(saw.range(-90, 90).slow(16))
  .distance(2).posglide(.5).gain(.26)

// Pebbles knocking in the current
pebbles: s("click*8?0.3").lpf(1500).speed(rand.range(.5, 1)).azimuth(rand.range(-60, 60))
  .distance(2).seed("pebbles").gain(.08)

// A dipper calling from a rock, and a breeze in the pines above
dipper: s("bird").slow(3).azimuth(40).distance(3).gain(.2)
breeze: s("wind").slow(8).intensity(.25).elevation(30).gain(.08)

// A waterfall, far off behind the trees
falls: s("brown").slow(8).lpf(600).azimuth(-130).distance(8).gain(.08)

setcpm(50/4)

// The waves rolling in
surf: s("surf").slow(8).intensity(.45).gain(.32)

// The shingle rattling as every other wave draws back
shingle: s("click*16?0.3").hpf(2000).distance(3).mask("<0 1 0 1>").seed("shingle").gain(.06)

// Sea spray: unrelated hiss in each ear, wide and all around
spray: s("pink").slow(8).icorr(.15).hpf(2500).lpf(7000).gain(.02)

// Gulls wheeling high overhead, and the wind off the sea
gulls: s("bird").slow(4).azimuth(saw.range(-120, 120).slow(16)).elevation(40)
  .distance(9).posglide(.5).gain(.14)
wind: s("wind").slow(8).intensity(.3).gain(.08)

setcpm(56/4)

// Crickets in the grass on either side
grass: s("insect").slow(4).azimuth(-100).distance(4).gain(.1)
field: s("insect").slow(4).azimuth(110).distance(6).gain(.08)

// Close chirps, each from a new place around you
chirps: s("click*8?0.5").hpf(4000).azimuth(rand.range(-180, 180)).distance(rand.range(1, 3))
  .seed("chirps").gain(.06)

// Frogs at the pond behind you
frogs: s("click*4?0.4").lpf(1200).azimuth(170).distance(5).seed("pond").gain(.1)

// An owl, far off to the left
owl: note("<~ [~ ~ d4 [d4 a3]] ~ ~>").s("hum").azimuth(-70).distance(8)
  .attack(.05).release(.5).gain(.12)

// The night air, barely moving
air: s("wind").slow(8).intensity(.1).gain(.04)

setcpm(52/4)

// The fire, close in front of you
fire: s("fire").slow(4).intensity(.5).density(10).distance(1.5).gain(.3)

// A log settling in the embers, now and then
logs: s("~ ~ creak ~").mask("<0 1 0 0 0 0 1 0>").speed(.6).lpf(1500).distance(1.5).gain(.12)

// Sparks popping, a few at a time
sparks: s("click*8?0.3").hpf(3000).azimuth(rand.range(-30, 30)).elevation(rand.range(0, 30))
  .distance(1.5).seed("sparks").gain(.06)

// Crickets in the dark, and wind in the trees around the clearing
crickets: s("insect").slow(4).azimuth(-100).distance(6).gain(.06)
trees: s("wind").slow(8).intensity(.2).elevation(20).distance(5).gain(.07)

setcpm(50/4)

// The wind over the ridge
wind: s("wind").slow(8).intensity(.6).gain(.18)

// Gusts: each ear has its own low-pass, sweeping in opposite directions,
// so the brightness wanders between the ears while the level stays put
gusts: s("pink*4").hpf(200).attack(.3).release(.6)
  .lcutoff(saw.range(500, 3000).slow(8)).rcutoff(isaw.range(500, 3000).slow(8)).gain(.05)

// A lone pine creaking in the wind, off to the right
pine: s("~ creak ~ ~").mask("<1 0 1 0 0 1 0 0>").speed(.7).azimuth(60).distance(4).gain(.12)

// Grass hissing at your feet
grass: s("white").slow(8).hpf(4000).lpf(8000).elevation(-40).distance(1).gain(.015)

// A raven calling far below
raven: s("bird").slow(8).azimuth(-60).elevation(-30).distance(12).gain(.1)

setcpm(56/4)

// The rain above the canopy, muffled by the leaves
rain: s("rain").slow(4).intensity(.6).elevation(40).distance(3).occlude(.4).gain(.28)

// Heavy drops falling through the leaves around you
drops: s("drip*8?0.4").speed(rand.range(.6, 1)).azimuth(rand.range(-180, 180))
  .elevation(rand.range(10, 60)).distance(rand.range(1, 3)).seed("canopy").gain(.16)

// A stream swelling with the rain, nearby on your right
stream: s("stream").slow(4).intensity(.5).azimuth(70).distance(3).gain(.16)

// A bird singing from somewhere in the wet
bird: s("bird").slow(5).azimuth(-110).elevation(20).distance(6).occlude(.3).gain(.12)

setcpm(48/4)

// The sea outside, heard through the rock
surf: s("surf").slow(8).intensity(.55).occlude(.5).space("church").room(.5).gain(.3)

// Water dripping from the roof at points around you, ringing in the stone
drips: s("drip*8?0.6").azimuth(rand.range(-180, 180)).elevation(rand.range(20, 70))
  .distance(rand.range(1, 4)).seed("cave").space("church").room(.5).gain(.16)

// A trickle running down the wall to your left
trickle: s("stream").slow(4).intensity(.15).azimuth(-80).distance(2).space("church").gain(.1)

// The low boom of the cave itself
boom: s("brown").slow(8).lpf(200).gain(.12)

setcpm(64/4)

// Grasshoppers all around you in the long grass
left: s("insect").slow(4).azimuth(-90).elevation(-20).distance(3).gain(.1)
right: s("insect").slow(4).azimuth(90).elevation(-20).distance(4).gain(.09)

// A bee circling your head every two bars, another the other way, slower and further out
bee1: s("insect*8").azimuth(saw.range(-180, 180).slow(2)).distance(1.2).posglide(.1).gain(.08)
bee2: s("insect*8").azimuth(isaw.range(-180, 180).slow(4)).elevation(10).distance(2.5).posglide(.1).gain(.06)

// Warm wind in the grass, and a skylark singing high above
wind: s("wind").slow(8).intensity(.25).gain(.08)
skylark: s("bird").slow(2).elevation(70).distance(10).gain(.14)

// A brook at the bottom of the field
brook: s("stream").slow(4).azimuth(160).distance(9).gain(.1)

setcpm(48/4)

// A cold wind across the open ice
wind: s("wind").slow(8).intensity(.4).gain(.14)

// Snow blowing across the surface: wide and different in each ear
snow: s("pink").slow(8).icorr(.15).hpf(3000).lpf(7000).gain(.02)

// Your own footsteps, crunching in the snow
steps: s("step ~ step ~").lpf(1800).elevation(-30).distance(1).gain(.12)

// The ice booming and cracking far out across the lake, from a new place each time
ice: s("~ ~ ~ creak").mask("<0 0 1 0 0 0 0 1>").speed(.4)
  .azimuth("<-60 40 -120 90>").distance(10).room(.6).gain(.16)
boom: s("<~ ~ ~ ~ ~ [~ lt] ~ ~>").speed(.3).lpf(200).azimuth(120).distance(12).room(.8).gain(.3)
